import requests

fp_names = ['mCherry', 'TagRFP', 'TagRFP675', 'PSmOrange', 'mAzamiGreen', 'GFP', 'EGFP', 'Clover', 'mClover3', 'mNeonGreen', 'YFP', 'Citrine', 'Venus']

for name in fp_names:
    url = f'https://www.fpbase.org/api/proteins/?name={name}&format=json'
    r = requests.get(url)
    data = r.json()
    if isinstance(data, list):
        results = data
    elif isinstance(data, dict):
        results = data.get('results', [data])
    else:
        results = []
    for fp in results[:1]:
        states = fp.get('states', [])
        for state in states:
            ex_max = state.get('ex_max')
            em_max = state.get('em_max')
            print(f"{fp.get('name', name)}: ex_max={ex_max}, em_max={em_max}")
